-- Veterans to Beekeepers isolated backend in shared Supabase project.
create extension if not exists pgcrypto;
create or replace function public.veterans_normalize_email(value text) returns text language sql immutable as $$ select lower(trim(coalesce(value, ''))) $$;
create table if not exists public.veterans_admins(id uuid primary key default gen_random_uuid(),email text not null unique,role text not null check(role in('owner','admin')),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint veterans_admins_email_normalized check(email=public.veterans_normalize_email(email)));
create table if not exists public.veterans_products(id uuid primary key default gen_random_uuid(),name text not null check(char_length(trim(name)) between 1 and 120),description text not null default '',price_minor_units integer not null check(price_minor_units>=0),currency text not null default 'USD' check(currency~'^[A-Z]{3}$'),stock_quantity integer not null default 0 check(stock_quantity>=0),image_path text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.veterans_orders(id uuid primary key default gen_random_uuid(),paypal_order_id text not null unique,paypal_capture_id text unique,payment_status text not null default 'PENDING' check(payment_status in('PENDING','COMPLETED','CANCELLED','FAILED','REFUNDED')),fulfillment_status text not null default 'New' check(fulfillment_status in('New','Processing','Shipped','Completed','Cancelled')),total_minor_units integer not null check(total_minor_units>=0),currency text not null default 'USD',customer_email text,shipping_json jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.veterans_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.veterans_orders(id) on delete cascade,product_id uuid references public.veterans_products(id) on delete set null,product_name_snapshot text not null,unit_price_minor_units integer not null check(unit_price_minor_units>=0),quantity integer not null check(quantity between 1 and 99),created_at timestamptz not null default now());
create table if not exists public.veterans_chat_messages(id uuid primary key default gen_random_uuid(),guest_id uuid not null,display_name text not null check(char_length(trim(display_name)) between 1 and 40),body text not null default '' check(char_length(body)<=1000),image_path text,created_at timestamptz not null default now(),deleted_at timestamptz,constraint veterans_chat_content_present check(char_length(trim(body))>0 or image_path is not null));
create table if not exists public.veterans_chat_blocks(id uuid primary key default gen_random_uuid(),guest_id uuid not null unique,reason text not null default '',blocked_by_admin_email text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.veterans_site_settings(key text primary key,value_json jsonb not null default '{}'::jsonb,public_read boolean not null default false,updated_at timestamptz not null default now());
create or replace function public.veterans_current_user_email() returns text language sql stable as $$ select public.veterans_normalize_email(auth.jwt()->>'email') $$;
create or replace function public.veterans_is_active_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.veterans_admins where email=public.veterans_current_user_email() and active=true) $$;
create or replace function public.veterans_is_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.veterans_admins where email=public.veterans_current_user_email() and active=true and role='owner') $$;
alter table public.veterans_admins enable row level security;alter table public.veterans_products enable row level security;alter table public.veterans_orders enable row level security;alter table public.veterans_order_items enable row level security;alter table public.veterans_chat_messages enable row level security;alter table public.veterans_chat_blocks enable row level security;alter table public.veterans_site_settings enable row level security;
create policy veterans_admins_read on public.veterans_admins for select to authenticated using(email=public.veterans_current_user_email() or public.veterans_is_owner());
create policy veterans_products_read on public.veterans_products for select to anon,authenticated using(active=true or public.veterans_is_active_admin());
create policy veterans_products_admin_insert on public.veterans_products for insert to authenticated with check(public.veterans_is_active_admin());create policy veterans_products_admin_update on public.veterans_products for update to authenticated using(public.veterans_is_active_admin()) with check(public.veterans_is_active_admin());create policy veterans_products_admin_delete on public.veterans_products for delete to authenticated using(public.veterans_is_active_admin());
create policy veterans_orders_admin_read on public.veterans_orders for select to authenticated using(public.veterans_is_active_admin());create policy veterans_orders_admin_update on public.veterans_orders for update to authenticated using(public.veterans_is_active_admin()) with check(public.veterans_is_active_admin());create policy veterans_order_items_admin_read on public.veterans_order_items for select to authenticated using(public.veterans_is_active_admin());
create policy veterans_chat_public_read on public.veterans_chat_messages for select to anon,authenticated using(deleted_at is null);create policy veterans_chat_admin_read_all on public.veterans_chat_messages for select to authenticated using(public.veterans_is_active_admin());create policy veterans_chat_admin_update on public.veterans_chat_messages for update to authenticated using(public.veterans_is_active_admin()) with check(public.veterans_is_active_admin());create policy veterans_chat_admin_delete on public.veterans_chat_messages for delete to authenticated using(public.veterans_is_active_admin());create policy veterans_chat_blocks_admin_all on public.veterans_chat_blocks for all to authenticated using(public.veterans_is_active_admin()) with check(public.veterans_is_active_admin());
grant select on public.veterans_products to anon,authenticated;grant insert,update,delete on public.veterans_products to authenticated;grant select,update on public.veterans_orders to authenticated;grant select on public.veterans_order_items to authenticated;grant select on public.veterans_chat_messages to anon,authenticated;grant select,insert,update,delete on public.veterans_chat_blocks to authenticated;grant select on public.veterans_admins to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('veterans-product-images','veterans-product-images',true,5242880,array['image/jpeg','image/png','image/webp']),('veterans-chat-images','veterans-chat-images',true,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy veterans_storage_public_read on storage.objects for select to anon,authenticated using(bucket_id in('veterans-product-images','veterans-chat-images'));create policy veterans_product_images_admin_insert on storage.objects for insert to authenticated with check(bucket_id='veterans-product-images' and public.veterans_is_active_admin());create policy veterans_product_images_admin_update on storage.objects for update to authenticated using(bucket_id='veterans-product-images' and public.veterans_is_active_admin()) with check(bucket_id='veterans-product-images' and public.veterans_is_active_admin());create policy veterans_product_images_admin_delete on storage.objects for delete to authenticated using(bucket_id='veterans-product-images' and public.veterans_is_active_admin());create policy veterans_chat_images_admin_delete on storage.objects for delete to authenticated using(bucket_id='veterans-chat-images' and public.veterans_is_active_admin());
create or replace function public.veterans_finalize_capture(p_paypal_order_id text,p_capture_id text,p_customer_email text,p_shipping_json jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_order public.veterans_orders%rowtype;v_item public.veterans_order_items%rowtype;begin select * into v_order from public.veterans_orders where paypal_order_id=p_paypal_order_id for update;if not found then raise exception 'order not found';end if;if v_order.payment_status = 'COMPLETED' then return v_order.id;end if;for v_item in select * from public.veterans_order_items where order_id=v_order.id loop update public.veterans_products set stock_quantity=stock_quantity-v_item.quantity where id=v_item.product_id and active=true and stock_quantity>=v_item.quantity;if not found then raise exception 'insufficient stock';end if;end loop;update public.veterans_orders set paypal_capture_id=p_capture_id,payment_status='COMPLETED',customer_email=nullif(trim(p_customer_email),''),shipping_json=p_shipping_json,updated_at=now() where id=v_order.id;return v_order.id;end $$;revoke all on function public.veterans_finalize_capture(text,text,text,jsonb) from public,anon,authenticated;grant execute on function public.veterans_finalize_capture(text,text,text,jsonb) to service_role;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='veterans_chat_messages') then alter publication supabase_realtime add table public.veterans_chat_messages;end if;end $$;
